const data = $input.first().json;
const actor = data.body || data;
const description = actor.Description || '';

const shotTypes = ['close-up POV portrait', 'mid-shot snapshot'];
const lightSources = ['a nearby window', 'soft overcast sky', 'golden hour sun from the side'];
const distances = ['very close to the lens', 'at a comfortable speaking distance'];
const gazes = ['directly into the lens', 'directly into the lens', 'slightly off-camera'];
const energies = ['raw POV energy', 'candid UGC snapshot energy'];
const backgrounds = [
  'a softly blurred living room with neutral tones',
  'a clean bathroom with soft natural light',
  'a casual home office setting',
  'an outdoor patio with greenery'
];

const pick = arr => arr[Math.floor(Math.random() * arr.length)];

const prompt = `A vertical 9:16 ${pick(shotTypes)} captured on an iPhone 16 Pro at high resolution, with the typical computational look of a real smartphone photo: natural soft daylight coming from ${pick(lightSources)}, creating gentle highlights and subtle falloff. A ${description} stands ${pick(distances)}, filling the frame. Their skin is completely clean and natural with fully realistic texture: visible pores on the cheeks and nose, natural skin variations, and soft lighting falloff. Their expression is warm and authentic, eyes looking ${pick(gazes)}. Hands not visible. Only one person in the frame, no other people visible, no partial figures, no bystanders. The background is ${pick(backgrounds)}, slight depth of field. The lighting is unfiltered and true to life, preserving fine facial details. No filters, no retouching, no timestamps, no date stamps, no watermarks, no text overlays, no camera UI, no viewfinder, no shutter buttons, no "PORTRAIT" text, no phone interface elements of any kind — full realistic ${pick(energies)}.`;

return [{ json: { ...actor, prompt } }];

const original = $('Build Actor Prompt').first().json;
const falResponse = $input.first().json;

const imageUrl = falResponse.images[0].url;

return [{
  json: {
    id: original.id,
    Name: original.Name,
    imageUrl: imageUrl,
    prompt: original.prompt
  }
}];

const scene = $('Fetch Scene').first().json;
const actor = $('Fetch Actor').first().json;
const product = $input.first().json;

let productImageUrl = null;
let productName = null;

if (product && product.id && product['Product Image']?.[0]?.url) {
  productImageUrl = product['Product Image'][0].url;
  productName = product.Name || null;
}

const actorImageUrl = actor.Photo?.[0]?.url || '';
const actorName = actor.Name || '';
const voiceId = scene['Voice ID']?.[0] || 'cgSgspJ2msm6clMCkdW9';

return [{
  json: {
    sceneId: scene.id,
    dialogue: scene.Dialogue,
    scenePreset: scene['Scene Preset'],
    mode: scene.Mode,
    action: scene.Action || '',
    actorName: actorName,
    actorImageUrl: actorImageUrl,
    productName: productName,
    productImageUrl: productImageUrl,
    hasProduct: !!productImageUrl,
    voiceId: voiceId
  }
}];

const mergedData = $('Merge Data').first().json;
const audioResponse = $input.first().json;

let actionText = '';
if (mergedData.action) {
  actionText = `, ${mergedData.action}`;
}

const webhookUrl = "https://mikefutia.app.n8n.cloud/webhook/28a54a6d-537f-4d5a-b267-7a9ae0351ab5?type=scene&id=" + mergedData.sceneId;

return [{
  json: {
    sceneId: mergedData.sceneId,
    image_url: mergedData.actorImageUrl,
    audio_url: audioResponse.audio.url,
    prompt: `A person speaking directly to camera, natural UGC selfie style${actionText}`,
    webhookUrl: encodeURIComponent(webhookUrl)
  }
}];

const data = $input.first().json;

let actionText = '';
if (data.action) {
  actionText = `\n\nActions/expressions: ${data.action}`;
}

const prompt = `A casual selfie-style iPhone video. A person speaks directly to camera with natural energy and authentic expression.

They say: "${data.dialogue}"${actionText}

UGC style: handheld realism, direct eye contact, natural lighting, genuine emotion, raw unfiltered aesthetic.`;

const webhookUrl = "https://mikefutia.app.n8n.cloud/webhook/28a54a6d-537f-4d5a-b267-7a9ae0351ab5?type=scene&id=" + data.sceneId;

return [{
  json: {
    sceneId: data.sceneId,
    webhookUrl: encodeURIComponent(webhookUrl),
    falBody: {
      prompt: prompt,
      image_url: data.actorImageUrl,
      aspect_ratio: "9:16",
      duration: "8s",
      resolution: "720p",
      generate_audio: true
    }
  }
}];

const query = $input.first().json.query;
const body = $input.first().json.body;

const type = query.type;
const recordId = query.id;

// Check for error status
const isError = body?.status === "ERROR" || body?.payload?.status === "ERROR";
const errorMsg = body?.payload?.detail?.[0]?.msg || body?.error || null;

// Try multiple possible paths for video URL
const videoUrl = 
  body?.video?.url || 
  body?.payload?.video?.url || 
  body?.data?.video?.url ||
  body?.result?.video?.url ||
  null;

const thumbnailUrl = 
  body?.thumbnail?.url || 
  body?.payload?.thumbnail?.url ||
  null;

return [{
  json: {
    type,
    recordId,
    videoUrl,
    thumbnailUrl,
    isError,
    errorMsg
  }
}];

const data = $input.first().json;

let imageUrls = [];
let context = '';

// Start with parent actor photo if this is a variant
if (data.ParentActorPhotoUrl) {
  imageUrls.push(data.ParentActorPhotoUrl);
  context = data.Description;
} 

// Add product image if provided
if (data.ProductImageUrl) {
  imageUrls.push(data.ProductImageUrl);
  if (data.ParentActorPhotoUrl) {
    context = `holding the product naturally. ${data.Description}`;
  } else {
    context = `holding the product naturally. ${data.Description}`;
  }
}

const prompt = `A vertical 9:16 close-up selfie-style photo captured on an iPhone 16 Pro. This same person ${context}. They stand very close to the lens, filling the frame. Their expression is warm and authentic, eyes looking directly into the lens. Natural soft daylight, realistic skin texture with visible pores. The lighting is unfiltered and true to life. No filters, no retouching, no timestamps, no watermarks, no camera UI, no text overlays — full realistic UGC energy.`;

return [{
  json: {
    ...data,
    editBody: {
      prompt: prompt,
      image_urls: imageUrls,
      aspect_ratio: "9:16",
      resolution: "1K",
      output_format: "png"
    }
  }
}];

const input = $('Build Edit Request').first().json;
const result = $input.first().json;

const imageUrl = result.images?.[0]?.url || null;

return [{
  json: {
    id: input.id,
    Photo: imageUrl ? [{ url: imageUrl }] : null,
    Status: imageUrl ? 'Success' : 'Failed',
    prompt: input.editBody.prompt
  }
}];

const data = $input.first().json;
const imageUrl = data.imageUrl || data.Photo?.[0]?.url || null;

return [{
  json: {
    ...data,
    visionBody: {
      model: "gpt-4o-mini",
      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: "Analyze this person's photo. Respond with ONLY a JSON object (no markdown, no explanation) with these fields:\n- gender: \"Male\", \"Female\", or \"Non-binary\"\n- ethnicity: \"White\", \"Black\", \"Latino/Latina\", \"Asian\", \"Middle Eastern\", \"South Asian\", or \"Mixed\"\n- ageRange: \"18-25\", \"26-35\", \"36-45\", \"46-55\", or \"55+\""
            },
            {
              type: "image_url",
              image_url: { url: imageUrl }
            }
          ]
        }
      ],
      max_tokens: 100
    }
  }
}];

