const input = $('Build Vision Request').first().json;
const response = $input.first().json;

// Extract the text content (handle both OpenAI and Gemini formats)
let text = response.choices?.[0]?.message?.content || 
           response.content?.parts?.[0]?.text || 
           '';

// Remove markdown code blocks if present
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { gender: null, ethnicity: null, ageRange: null };
}

return [{
  json: {
    id: input.id,
    imageUrl: input.imageUrl,
    prompt: input.prompt,
    gender: parsed.gender || null,
    ethnicity: parsed.ethnicity || null,
    ageRange: parsed.ageRange || null
  }
}];

