const data = $input.first().json;
const body = data.body || data;

const hasParent = !!body.ParentActorPhotoUrl;
const hasProduct = !!body.ProductImageUrl;
const needsEdit = hasParent || hasProduct;

return [{
  json: {
    ...body,
    hasParent,
    hasProduct,
    needsEdit
  }
}];

const broll = $('Fetch B-Roll').first().json;
const product = $('Fetch Product').first().json;
const actor = $('Fetch Actor1').first().json;

// Use actor image if available, otherwise product image
const imageUrl = actor?.Photo?.[0]?.url || product?.['Product Image']?.[0]?.url || null;

const prompt = `${broll.Prompt}

Cinematic B-Roll footage. No dialogue, no speech, no talking. Smooth motion, professional quality.`;

const webhookUrl = "https://mikefutia.app.n8n.cloud/webhook/28a54a6d-537f-4d5a-b267-7a9ae0351ab5?type=broll&id=" + broll.id;

return [{
  json: {
    id: broll.id,
    sourceImageUrl: imageUrl,
    webhookUrl: encodeURIComponent(webhookUrl),
    falBody: {
      prompt: prompt,
      image_url: imageUrl,
      aspect_ratio: "9:16",
      duration: "8s",
      resolution: "720p",
      generate_audio: false
    }
  }
}];

const items = $input.all();

return items.map(item => {
  const voice = item.json;

  // Capitalize gender
  let gender = voice.labels?.gender || 'unknown';
  gender = gender.charAt(0).toUpperCase() + gender.slice(1);

  // Format age
  let age = voice.labels?.age || 'unknown';
  if (age === 'middle_aged') age = 'Middle-aged';
  else if (age === 'young') age = 'Young';
  else if (age === 'old') age = 'Old';

  return {
    json: {
      fields: {
        "Name": voice.name,
        "Voice ID": voice.voice_id,
        "Preview Audio": [{ url: voice.preview_url }],
        "Gender": gender,
        "Age": age
      }
    }
  };
});
